// Mini serveur WebSocket (sous-ensemble de « ws ») pour les tests hors ligne : poignée de main, trames binaires, ping/close.
const http=require('http'),crypto=require('crypto'),{EventEmitter}=require('events'),{Duplex}=require('stream');
class Conn extends EventEmitter{constructor(sock){super();this.s=sock;this.buf=Buffer.alloc(0);this.open=true;sock.on('data',d=>{this.buf=Buffer.concat([this.buf,d]);this.parse()});sock.on('close',()=>{if(this.open){this.open=false;this.emit('close')}});sock.on('error',()=>{})}
 parse(){for(;;){const b=this.buf;if(b.length<2)return;const op=b[0]&15,masked=b[1]&128;let len=b[1]&127,o=2;if(len===126){if(b.length<4)return;len=b.readUInt16BE(2);o=4}else if(len===127){if(b.length<10)return;len=Number(b.readBigUInt64BE(2));o=10}
  const mo=o;if(masked)o+=4;if(b.length<o+len)return;let p=b.subarray(o,o+len);if(masked){const m=b.subarray(mo,mo+4);p=Buffer.from(p);for(let i=0;i<p.length;i++)p[i]^=m[i&3]}this.buf=b.subarray(o+len);
  if(op===8){this.close();return}if(op===9){this.frame(10,p);continue}if(op===10)continue;this.emit('message',Buffer.from(p))}}
 frame(op,p){if(!this.open)return;const n=p.length;let h;if(n<126)h=Buffer.from([128|op,n]);else if(n<65536){h=Buffer.alloc(4);h[0]=128|op;h[1]=126;h.writeUInt16BE(n,2)}else{h=Buffer.alloc(10);h[0]=128|op;h[1]=127;h.writeBigUInt64BE(BigInt(n),2)}try{this.s.write(Buffer.concat([h,p]))}catch(e){}}
 send(d){this.frame(2,Buffer.from(d))}close(){if(!this.open)return;try{this.s.write(Buffer.from([0x88,0]))}catch(e){}this.terminate()}terminate(){if(this.open){this.open=false;this.emit('close')}try{this.s.destroy()}catch(e){}}}
class WebSocketServer extends EventEmitter{constructor(o){super();this.clients=new Set();this.srv=http.createServer((q,r)=>{r.writeHead(426);r.end()});
 this.srv.on('upgrade',(req,sock)=>{const k=req.headers['sec-websocket-key'];if(!k){sock.destroy();return}const acc=crypto.createHash('sha1').update(k+'258EAFA5-E914-47DA-95CA-C5AB0DC85B11').digest('base64');
  const ps=new Set(String(req.headers['sec-websocket-protocol']||'').split(',').map(s=>s.trim()).filter(Boolean)),pr=o.handleProtocols?o.handleProtocols(ps):null;
  sock.write('HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: '+acc+'\r\n'+(pr?'Sec-WebSocket-Protocol: '+pr+'\r\n':'')+'\r\n');sock.setNoDelay(true);
  const c=new Conn(sock);this.clients.add(c);c.on('close',()=>this.clients.delete(c));this.emit('connection',c,req)});this.srv.listen(o.port,'127.0.0.1')}
 close(){for(const c of this.clients)c.terminate();this.srv.close()}}
function createWebSocketStream(ws){const d=new Duplex({read(){},write(ch,enc,cb){ws.send(ch);cb()},final(cb){ws.close();cb()}});ws.on('message',m=>d.push(m));ws.on('close',()=>{d.push(null);d.emit('close')});return d}
module.exports={WebSocketServer,createWebSocketStream};
